('b70de6f9-5f56-59c0-8a45-d09b5dde90c6'::uuid,'est','"Functions, Transformations & Graphs"'::jsonb,'hard','mcq','"If f(x) = x − 2 and g(x) = x − 3, then f(g(x)) ="'::jsonb,'[{"key":"A","text":"f(x) − 1"},{"key":"B","text":"f(x) − 2"},{"key":"C","text":"f(x) − 3"},{"key":"D","text":"f(x) − 4"},{"key":"E","text":"f(x) − 5"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t7.md","source_sha256":"0fb6c459b96ac5b60a4c189de7328ebcb6d3bb964b72869331be58aa609b2ef5","source_question_id":"T7-49","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Functions, Transformations & Graphs"}'::jsonb,'"D"'::jsonb,'"Source-keyed answer from book_t7.md (T7-49)."'::jsonb),
('90f1e398-170b-5c9b-a972-5b29ce57c3a6'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"In a circle of radius 6, the distance from chord AB to the center of the circle is 4. How long is chord AB?"'::jsonb,'[{"key":"A","text":"4.5"},{"key":"B","text":"8"},{"key":"C","text":"8.9"},{"key":"D","text":"10"},{"key":"E","text":"10.4"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t7.md","source_sha256":"0fb6c459b96ac5b60a4c189de7328ebcb6d3bb964b72869331be58aa609b2ef5","source_question_id":"T7-50","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from book_t7.md (T7-50)."'::jsonb),
