('1f8293d6-a23c-5364-8f0a-9f05b37f5041'::uuid,'est','"Coordinate Geometry, Circles & Conics"'::jsonb,'medium','mcq','"[Figure: Parabola opening downward from (0, 6), vertex (110, 36), landing at (230, 0); golfer at tee box.]\nA golfer hit a golf ball from a tee box that is 6 yards above the ground. The graph shows the height in yards of the golf ball above the ground as a quadratic function of x, the horizontal distance in yards of the golf ball from the tee box. What is the domain of the function for this situation?"'::jsonb,'[{"key":"F","text":"0 ≤ x ≤ 230"},{"key":"G","text":"6 ≤ y ≤ 36"},{"key":"H","text":"0 ≤ y ≤ 36"},{"key":"J","text":"6 ≤ x ≤ 230"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t8.md","source_sha256":"8f03df34fa98881a0531e925df7d2a108b1590182b68af8e273abe0930b44cfb","source_question_id":"T8-03","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Coordinate Geometry, Circles & Conics"}'::jsonb,'"F"'::jsonb,'"Source-keyed answer from book_t8.md (T8-03)."'::jsonb),
('a5641998-19a1-548d-bb6e-df39b1001127'::uuid,'est','"Polynomials & Quadratic Functions"'::jsonb,'medium','mcq','"Which function is equivalent to g(x) = x² + 15x − 54?"'::jsonb,'[{"key":"F","text":"g(x) = (x + 9)(x − 6)"},{"key":"G","text":"g(x) = (x + 18)(x − 3)"},{"key":"H","text":"g(x) = (x − 9)(x + 6)"},{"key":"J","text":"g(x) = (x − 18)(x + 3)"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t8.md","source_sha256":"8f03df34fa98881a0531e925df7d2a108b1590182b68af8e273abe0930b44cfb","source_question_id":"T8-04","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Polynomials & Quadratic Functions"}'::jsonb,'"G"'::jsonb,'"Source-keyed answer from book_t8.md (T8-04)."'::jsonb),
('52651084-2ff0-5e01-90b2-889962766235'::uuid,'est','"Functions, Transformations & Graphs"'::jsonb,'medium','mcq','"The table shows the linear relationship between the average height in feet of trees on a tree farm and the number of years since the trees were planted.\nYears since planted: 1, 3, 6, 11, 15\nAverage height (ft): 10, 24, 45, 80, 108\nWhat is the rate of change of the average height in feet of the trees with respect to the number of years since the trees were planted?"'::jsonb,'[{"key":"A","text":"14 ft/yr"},{"key":"B","text":"3 ft/yr"},{"key":"C","text":"7 ft/yr"},{"key":"D","text":"10 ft/yr"}]'::jsonb,'{"source":"Kimi Agent Math PDF Question Bank (4)","source_file":"book_t8.md","source_sha256":"8f03df34fa98881a0531e925df7d2a108b1590182b68af8e273abe0930b44cfb","source_question_id":"T8-05","import_batch":"est2-kimi-bank-2026-09-21","curriculum_lesson":"Functions, Transformations & Graphs"}'::jsonb,'"C"'::jsonb,'"Source-keyed answer from book_t8.md (T8-05)."'::jsonb),
